--
-- Database: `campus_db`
--

DELIMITER $$
--
-- Procedures
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `generate_lecturers` ()  BEGIN
    DECLARE d INT DEFAULT 1;
    DECLARE i INT;
    DECLARE lid INT;

    WHILE d <= 8 DO
        SET i = 0;

        WHILE i < 13 DO
            SET lid = d * 100 + i;

            INSERT INTO Lecturer
            VALUES (
                lid,
                CONCAT('Lecturer_', lid),
                'Specialist',
                CONCAT('lect', lid, '@campus.ac.id'),
                d
            );

            SET i = i + 1;
        END WHILE;

        SET d = d + 1;
    END WHILE;
END$$

DELIMITER ;

